function fix(lang, s) {
  if (lang === 'et') return s.replace(/([Pp])rivaatus/g, '$1rivaatsus').replace(/PRIVAATUS/g, 'PRIVAATSUS');
  if (lang === 'it') return s.split('qrcrete').join('qrcreate');
  if (lang === 'no') {
    let n = s;
    n = n.split('1. RETNINGSLINJER FOR PERSONVERN').join('1. PERSONVERNERKLÆRING');
    n = n.split('har lest våre <PrivacyPolicyLink>retningslinjer for personvern</PrivacyPolicyLink>').join('har lest vår <PrivacyPolicyLink>personvernerklæring</PrivacyPolicyLink>');
    n = n.split('bekrefter våre <PrivacyPolicyLink>retningslinjer for personvern</PrivacyPolicyLink>').join('bekrefter vår <PrivacyPolicyLink>personvernerklæring</PrivacyPolicyLink>');
    n = n.replace(/([Vv])åre? (<a [^>]*><u>)Retningslinjer for personvern(<\/u><\/a>)/g, '$1år $2Personvernerklæring$3');
    if (n.trim() === 'Retningslinjer for personvern') n = 'Personvernerklæring';
    return n;
  }
  return s;
}
const LEFT = { et: /privaatus/i, it: /qrcrete/i, no: /etningslinje\w* for personvern/i };
const byP = {}; const changes = []; const leftover = [];
for (const it of $input.all()) {
  const b = it.json || {}; const pid = b.project_id; if (!pid) continue;
  for (const k of (b.keys || [])) {
    const trs = [];
    for (const t of (k.translations || [])) {
      const l = t.language_iso; if (!LEFT[l]) continue;
      const cur = t.translation || ''; const nw = fix(l, cur);
      if (LEFT[l].test(nw)) leftover.push({ key: k.key_name.web, lang: l, text: nw.slice(0, 250) });
      if (nw !== cur) { trs.push({ language_iso: l, translation: nw }); changes.push({ pid: pid.slice(0, 4), key: k.key_name.web, lang: l, before: cur, after: nw }); }
    }
    if (trs.length) (byP[pid] = byP[pid] || []).push({ key_id: k.key_id, translations: trs });
  }
}
const out = Object.keys(byP).map(pid => ({ json: { pid, body: { keys: byP[pid] }, n: byP[pid].length, changes, leftover } }));
if (!out.length) return [{ json: { pid: null, n: 0, changes, leftover } }];
return out;
